import { Suspense, useCallback, useEffect, useMemo, useState } from "react";
import { Canvas } from "@react-three/fiber";
import { Link } from "react-router-dom";
import { useTranslation } from "react-i18next";
import {
  ArrowLeft,
  Play,
  Pause,
  SkipBack,
  SkipForward,
  Sparkles,
  CircleDot,
  Aperture,
  Orbit,
  Layers,
  TreePine,
  Mountain,
  Compass,
  Settings2,
} from "lucide-react";
import { SeoHead } from "../../components/SeoHead";
import { DroneScene } from "./scene/DroneScene";
import {
  useDroneShowStore,
  droneCountForTier,
  type SceneQuality,
} from "./store";
import { FORMATION_ORDER, FORMATION_META } from "./formations";

const FORMATION_ICONS: Record<string, React.ComponentType<{ size?: number }>> = {
  taiji:        CircleDot,
  baguaArray:   Compass,
  phoenix:      Sparkles,
  worldTree:    TreePine,
  orbitalChart: Orbit,
  pavilion:     Layers,
  greatWall:    Mountain,
};

/**
 * 光电渲染体验馆入口页
 * - Canvas + HUD（顶栏、启动遮罩、造型 dock、播控、统计）
 * - 键盘：Space=play/pause，←/→=prev/next，1-7=跳转，V=auto-orbit
 * - FPS 滚动窗口自适应 quality tier
 */
export function DroneShowPage() {
  const { t } = useTranslation();
  const [quality, setQuality] = useState<SceneQuality>("high");

  const started         = useDroneShowStore((s) => s.started);
  const formationIndex  = useDroneShowStore((s) => s.formationIndex);
  const playing         = useDroneShowStore((s) => s.playing);
  const speed           = useDroneShowStore((s) => s.speed);
  const autoOrbit       = useDroneShowStore((s) => s.autoOrbit);
  const morphProgress   = useDroneShowStore((s) => s.morphProgress);

  const start           = useDroneShowStore((s) => s.start);
  const togglePlaying   = useDroneShowStore((s) => s.togglePlaying);
  const cycleSpeed      = useDroneShowStore((s) => s.cycleSpeed);
  const nextFormation   = useDroneShowStore((s) => s.nextFormation);
  const prevFormation   = useDroneShowStore((s) => s.prevFormation);
  const setFormation    = useDroneShowStore((s) => s.setFormation);
  const toggleAutoOrbit = useDroneShowStore((s) => s.toggleAutoOrbit);
  const setQualityTier  = useDroneShowStore((s) => s.setQualityTier);
  const reset           = useDroneShowStore((s) => s.reset);

  // 离开页面时重置状态
  useEffect(() => () => reset(), [reset]);

  // ?auto=1 调试参数：跳过启动遮罩直接开演（镜像 experience 的 ?mode= 约定）
  // ?forceTier=high|medium|low：锁定画质档（绕过 FPS 自适应，便于 headless 截图验证）
  const urlParams = useMemo(() => new URLSearchParams(window.location.search), []);
  const forcedTier = useMemo(() => {
    const v = urlParams.get("forceTier");
    return v === "high" || v === "medium" || v === "low" ? v : null;
  }, [urlParams]);

  useEffect(() => {
    if (urlParams.get("auto") === "1") start();
  }, [start, urlParams]);

  // 同步本地 quality → store（forcedTier 优先）
  useEffect(() => {
    setQualityTier(forcedTier ?? quality);
  }, [quality, forcedTier, setQualityTier]);

  // FPS 监控（镜像 ExperiencePage3D 策略）
  useEffect(() => {
    let last = performance.now();
    let raf = 0;
    let ticker = 0;
    const times: number[] = [];
    const loop = (now: number) => {
      raf = requestAnimationFrame(loop);
      const delta = now - last;
      last = now;
      times.push(delta);
      if (times.length > 90) times.shift();
      ticker += 1;
      if (ticker % 120 === 0 && times.length === 90) {
        // forcedTier 锁定时跳过自适应，保持截图/调试一致性
        if (forcedTier) return;
        const average = times.reduce((sum, v) => sum + v, 0) / times.length;
        const fps = 1000 / average;
        setQuality((cur) => {
          if (fps < 24 && cur !== "low") return "low";
          if (fps < 34 && cur === "high") return "medium";
          return cur;
        });
      }
    };
    raf = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(raf);
  }, [forcedTier]);

  // 键盘快捷键
  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if (!started) return;
      switch (e.code) {
        case "Space":
          e.preventDefault();
          togglePlaying();
          break;
        case "ArrowRight":
        case "BracketRight":
          nextFormation();
          break;
        case "ArrowLeft":
        case "BracketLeft":
          prevFormation();
          break;
        case "Digit1": case "Numpad1": setFormation(0); break;
        case "Digit2": case "Numpad2": setFormation(1); break;
        case "Digit3": case "Numpad3": setFormation(2); break;
        case "Digit4": case "Numpad4": setFormation(3); break;
        case "Digit5": case "Numpad5": setFormation(4); break;
        case "Digit6": case "Numpad6": setFormation(5); break;
        case "Digit7": case "Numpad7": setFormation(6); break;
        case "KeyV":
          toggleAutoOrbit();
          break;
      }
    };
    window.addEventListener("keydown", handler);
    return () => window.removeEventListener("keydown", handler);
  }, [started, togglePlaying, nextFormation, prevFormation, setFormation, toggleAutoOrbit]);

  const handleStart = useCallback(() => {
    start();
  }, [start]);

  const currentMeta = FORMATION_META[FORMATION_ORDER[formationIndex]];
  const droneCount = droneCountForTier(quality);

  return (
    <>
      <SeoHead titleKey="seo.droneTitle" descriptionKey="seo.droneDescription" path="drone-show" />
      <main className="drone-page">
        <div className="drone-scene">
        <Canvas
          dpr={quality === "low" ? [1, 1] : [1, 1.5]}
          frameloop="always"
          camera={{ position: [0, 8, 22], fov: 42, near: 0.1, far: 200 }}
          // antialias 关闭：由后处理 SMAA(high)/FXAA(medium) 接管 AA，避免双重 AA 开销
          gl={{ antialias: false, powerPreference: "high-performance" }}
        >
          <Suspense fallback={null}>
            <DroneScene />
          </Suspense>
        </Canvas>
      </div>

      {/* 顶栏 */}
      <header className="drone-topbar">
        <Link className="drone-brand" to="/">
          <img src="./branding/hongyunx-mark.svg" alt="" />
          <span>
            <strong>{t("brand.name")}</strong>
            <small>PHOTOELECTRIC RENDERING</small>
          </span>
        </Link>
        <div className="drone-topbar__actions">
          <span className="drone-live"><i />{t("drone.live")}</span>
          <Link className="drone-exit" to="/">
            <ArrowLeft size={14} />
            {t("drone.exit")}
          </Link>
        </div>
      </header>

      {/* 启动遮罩 */}
      {!started && (
        <div className="drone-start" role="dialog" aria-modal="true">
          <div className="drone-start__card">
            <Sparkles size={32} className="drone-start__icon" />
            <h1>{t("drone.startTitle")}</h1>
            <p>{t("drone.startDescription")}</p>
            <button type="button" className="drone-start__action" onClick={handleStart}>
              {t("drone.startAction")}
            </button>
          </div>
        </div>
      )}

      {/* 底部造型 dock */}
      <nav className="drone-dock" aria-label={t("drone.formationsLabel")}>
        {FORMATION_ORDER.map((key, idx) => {
          const Icon = FORMATION_ICONS[key] ?? CircleDot;
          const active = idx === formationIndex;
          return (
            <button
              key={key}
              type="button"
              className={`drone-dock__item${active ? " is-active" : ""}`}
              onClick={() => setFormation(idx)}
              aria-pressed={active}
              title={`${t(`drone.formations.${key}`)} (${idx + 1})`}
            >
              <Icon size={18} />
              <span>{t(`drone.formations.${key}`)}</span>
              {active && <span className="drone-dock__progress" style={{ width: `${morphProgress * 100}%` }} />}
            </button>
          );
        })}
      </nav>

      {/* 播控条 */}
      <div className="drone-controls">
        <button type="button" onClick={prevFormation} aria-label={t("drone.controls.prev")}>
          <SkipBack size={16} />
        </button>
        <button type="button" onClick={togglePlaying} aria-label={playing ? t("drone.controls.pause") : t("drone.controls.play")}>
          {playing ? <Pause size={18} /> : <Play size={18} />}
        </button>
        <button type="button" onClick={nextFormation} aria-label={t("drone.controls.next")}>
          <SkipForward size={16} />
        </button>
        <button type="button" className="drone-speed" onClick={cycleSpeed} aria-label={t("drone.controls.speed")}>
          {speed}×
        </button>
        <button
          type="button"
          className={`drone-orbit${autoOrbit ? " is-on" : ""}`}
          onClick={toggleAutoOrbit}
          aria-pressed={autoOrbit}
          aria-label={t("drone.controls.orbit")}
        >
          <Aperture size={16} />
        </button>
      </div>

      {/* 统计徽章 */}
      <div className="drone-stats">
        <span>{currentMeta.label}</span>
        <span className="drone-stats__sep">·</span>
        <span>{droneCount.toLocaleString()} drones</span>
        <span className="drone-stats__sep">·</span>
        <span>{quality.toUpperCase()}</span>
      </div>

        {/* 帮助提示 */}
        <div className="drone-help">
          <Settings2 size={12} />
          <span>{t("drone.help")}</span>
        </div>
      </main>
    </>
  );
}

export default DroneShowPage;
