import { create } from "zustand";
import { FORMATION_ORDER, type FormationKey } from "./formations";

export type SceneQuality = "high" | "medium" | "low";
export type SpeedMultiplier = 0.5 | 1 | 2;

interface DroneShowState {
  started: boolean;
  formationIndex: number;
  playing: boolean;
  speed: SpeedMultiplier;
  autoOrbit: boolean;
  qualityTier: SceneQuality;
  morphProgress: number; // 0..1，仅用于 HUD 进度条显示

  start: () => void;
  setFormation: (index: number) => void;
  nextFormation: () => void;
  prevFormation: () => void;
  togglePlaying: () => void;
  cycleSpeed: () => void;
  toggleAutoOrbit: () => void;
  setQualityTier: (tier: SceneQuality) => void;
  setMorphProgress: (p: number) => void;
  reset: () => void;
}

const SPEEDS: SpeedMultiplier[] = [0.5, 1, 2];

export const useDroneShowStore = create<DroneShowState>((set, get) => ({
  started: false,
  formationIndex: 0,
  playing: true,
  speed: 1,
  autoOrbit: true,
  qualityTier: "high",
  morphProgress: 0,

  start: () => set({ started: true }),
  setFormation: (index) => {
    const len = FORMATION_ORDER.length;
    const i = ((index % len) + len) % len;
    set({ formationIndex: i, morphProgress: 0 });
  },
  nextFormation: () => {
    const { formationIndex } = get();
    const next = (formationIndex + 1) % FORMATION_ORDER.length;
    set({ formationIndex: next, morphProgress: 0 });
  },
  prevFormation: () => {
    const { formationIndex } = get();
    const prev = (formationIndex - 1 + FORMATION_ORDER.length) % FORMATION_ORDER.length;
    set({ formationIndex: prev, morphProgress: 0 });
  },
  togglePlaying: () => set((s) => ({ playing: !s.playing })),
  cycleSpeed: () =>
    set((s) => {
      const idx = SPEEDS.indexOf(s.speed);
      return { speed: SPEEDS[(idx + 1) % SPEEDS.length] };
    }),
  toggleAutoOrbit: () => set((s) => ({ autoOrbit: !s.autoOrbit })),
  setQualityTier: (tier) => set({ qualityTier: tier }),
  setMorphProgress: (p) => set({ morphProgress: p }),
  reset: () =>
    set({
      started: false,
      formationIndex: 0,
      playing: true,
      speed: 1,
      autoOrbit: true,
      morphProgress: 0,
    }),
}));

/** 根据 quality tier 决定无人机数量 */
export function droneCountForTier(tier: SceneQuality): number {
  switch (tier) {
    case "high":   return 10000;
    case "medium": return 4000;
    case "low":    return 1500;
  }
}

export function currentFormationKey(state: DroneShowState): FormationKey {
  return FORMATION_ORDER[state.formationIndex];
}
