import { useEffect, useMemo, useRef } from "react";
import { useFrame } from "@react-three/fiber";
import * as THREE from "three";
import { droneVertexShader, droneFragmentShader } from "./shaders";
import { buildFormation, FORMATION_ORDER } from "../formations";
import { mulberry32 } from "../rng";
import { droneCountForTier, useDroneShowStore, type SceneQuality } from "../store";
import { applyFormationToTargets, commitTargetsToCurrent } from "./swarmOps";

const MAX_DRONES = 10000;

// 每档画质的片元增强强度（low 全 0 = 零开销退化为原始软圆点）
const TIER_FX: Record<SceneQuality, { twinkle: number; spike: number }> = {
  high:   { twinkle: 0.45, spike: 0.7 },
  medium: { twinkle: 0.25, spike: 0.4 },
  low:    { twinkle: 0,    spike: 0 },
};

/**
 * GPU-morph 无人机群
 * - 单一 Points draw call，预分配 MAX_DRONES 容量
 * - setDrawRange 控制实际渲染数量（quality tier 切换时）
 * - morph 由 MorphDriver 写入 uniforms + target attributes
 */
export function DroneSwarm({ pointsRef }: { pointsRef: React.RefObject<THREE.Points | null> }) {
  const materialRef = useRef<THREE.ShaderMaterial>(null);

  // 预分配 typed arrays 并一次性填好初始数据（种子 + taiji 造型），
  // 全部在 useMemo 创建回调内完成，渲染后不再 mutate
  const buffers = useMemo(() => {
    const bufs = {
      position:      new Float32Array(MAX_DRONES * 3),
      aTarget:       new Float32Array(MAX_DRONES * 3),
      aColor:        new Float32Array(MAX_DRONES * 3),
      aTargetColor:  new Float32Array(MAX_DRONES * 3),
      aSeed:         new Float32Array(MAX_DRONES),
      aRing:         new Float32Array(MAX_DRONES),
      aTargetRing:   new Float32Array(MAX_DRONES),
    };
    // 确定性种子（纯函数，满足 react-hooks/purity；重渲染结果一致）
    const seedRand = mulberry32(1234);
    for (let i = 0; i < MAX_DRONES; i++) {
      bufs.aSeed[i] = seedRand();
    }
    const result = buildFormation("taiji", MAX_DRONES, 42);
    bufs.position.set(result.positions);
    bufs.aTarget.set(result.positions);
    bufs.aColor.set(result.colors);
    bufs.aTargetColor.set(result.colors);
    if (result.rings) {
      bufs.aRing.set(result.rings);
      bufs.aTargetRing.set(result.rings);
    }
    return bufs;
  }, []);

  // quality tier → draw range（初始全量；tier 切换时收缩）
  // 关键：tier 切换时仅调整 draw range + 用"当前活跃造型"重建 buffer，
  // 绝不硬重置为 taiji，否则 morph 中途会触发整帧粒子瞬移闪烁
  const qualityTier = useDroneShowStore((s) => s.qualityTier);
  const prevTierRef = useRef<SceneQuality | null>(null);
  useEffect(() => {
    if (!pointsRef.current) return;
    const count = droneCountForTier(qualityTier);
    pointsRef.current.geometry.setDrawRange(0, count);

    const isFirstMount = prevTierRef.current === null;
    prevTierRef.current = qualityTier;

    if (isFirstMount) {
      // 首帧：current = target = taiji，uMorph=0 → 画面即完整造型
      applyFormationToTargets(pointsRef.current, "taiji", count, 42);
      commitTargetsToCurrent(pointsRef.current, count);
    } else {
      // tier 热切换：用 store 中当前活跃造型重建 current/target，
      // MorphDriver 下一帧会继续驱动 morph，不会中断或跳帧
      const idx = useDroneShowStore.getState().formationIndex;
      const key = FORMATION_ORDER[idx] ?? "taiji";
      applyFormationToTargets(pointsRef.current, key, count);
      commitTargetsToCurrent(pointsRef.current, count);
    }
  }, [qualityTier, pointsRef]);

  // uTime 持续更新 + twinkle/spike 平滑过渡到当前 tier 目标值
  useFrame((state, delta) => {
    const mat = materialRef.current;
    if (!mat?.uniforms) return;
    const u = mat.uniforms;
    if (u.uTime) u.uTime.value = state.clock.elapsedTime;
    const target = TIER_FX[qualityTier];
    // damp 时间常数 ~0.3s，避免 tier 切换时闪烁突变
    if (u.uTwinkleAmp) {
      u.uTwinkleAmp.value = THREE.MathUtils.damp(u.uTwinkleAmp.value, target.twinkle, 4, delta);
    }
    if (u.uSpikeStrength) {
      u.uSpikeStrength.value = THREE.MathUtils.damp(u.uSpikeStrength.value, target.spike, 4, delta);
    }
  });

  // uniforms 对象（稳定引用）
  const uniforms = useMemo(
    () => ({
      uMorph:         { value: 0 },
      uTime:          { value: 0 },
      // 点尺寸基准：配合顶点着色器 (140 / -mvPosition.z) 的透视衰减，
      // 相机距离 ~24 时单点约 7px，保证点阵分离、不糊成一片
      uSize:          { value: 1.2 },
      uPixelRatio:    { value: Math.min(window.devicePixelRatio, 2) },
      // 片元增强强度：由 useFrame 按 tier 平滑过渡；初始 high 档
      uTwinkleAmp:    { value: 0.45 },
      uSpikeStrength: { value: 0.7 },
      // 旋转差速强度：仅 taiji↔baguaArray 切换态或两者 hold 态非零，由 MorphDriver 写入
      uSpin:          { value: 0 },
      // fog uniforms 占位：fog=true 时 three.js 的 refreshFogUniforms 会写入这些字段，
      // 缺少任一会导致 "Cannot read properties of undefined (reading 'value')" 崩溃
      fogColor:       { value: new THREE.Color(0x000000) },
      fogDensity:     { value: 0.02 },
      fogNear:        { value: 1 },
      fogFar:         { value: 1000 },
    }),
    [],
  );

  return (
    <points ref={pointsRef} frustumCulled={false}>
      <bufferGeometry>
        <bufferAttribute
          attach="attributes-position"
          args={[buffers.position, 3]}
          count={MAX_DRONES}
        />
        <bufferAttribute
          attach="attributes-aTarget"
          args={[buffers.aTarget, 3]}
          count={MAX_DRONES}
        />
        <bufferAttribute
          attach="attributes-aColor"
          args={[buffers.aColor, 3]}
          count={MAX_DRONES}
        />
        <bufferAttribute
          attach="attributes-aTargetColor"
          args={[buffers.aTargetColor, 3]}
          count={MAX_DRONES}
        />
        <bufferAttribute
          attach="attributes-aSeed"
          args={[buffers.aSeed, 1]}
          count={MAX_DRONES}
        />
        <bufferAttribute
          attach="attributes-aRing"
          args={[buffers.aRing, 1]}
          count={MAX_DRONES}
        />
        <bufferAttribute
          attach="attributes-aTargetRing"
          args={[buffers.aTargetRing, 1]}
          count={MAX_DRONES}
        />
      </bufferGeometry>
      <shaderMaterial
        ref={materialRef}
        vertexShader={droneVertexShader}
        fragmentShader={droneFragmentShader}
        uniforms={uniforms}
        transparent
        depthWrite={false}
        blending={THREE.AdditiveBlending}
        fog
      />
    </points>
  );
}
