/**
 * 光电渲染造型库
 *
 * 每个 builder 接收 (count, seed) → { positions: Float32Array, colors: Float32Array }
 * - count：目标点数（已按 quality tier 缩放）
 * - seed：确定性采样种子，保证同造型多次构建结果一致
 *
 * 颜色约定：RGB 各分量 ≤ 0.85，避免 Bloom 过曝；additive blending 下叠加会自然提亮。
 */

import { mulberry32 } from "./rng";

export type FormationKey =
  | "taiji" | "baguaArray" | "phoenix" | "worldTree" | "orbitalChart" | "pavilion" | "greatWall";

export interface FormationResult {
  positions: Float32Array; // xyz × count
  colors: Float32Array;    // rgb × count
  rings: Float32Array;     // per-particle ring group 0..7（ring-staggered morph / 旋转差速）
}

export const FORMATION_ORDER: FormationKey[] = [
  "taiji",
  "baguaArray",
  "phoenix",
  "worldTree",
  "orbitalChart",
  "pavilion",
  "greatWall",
];

export const FORMATION_META: Record<FormationKey, { label: string; idleRotateY?: number }> = {
  taiji:         { label: "太极",         idleRotateY: 0.15 },
  baguaArray:    { label: "九宫八卦阵",   idleRotateY: 0.1 },
  phoenix:       { label: "朱雀",         idleRotateY: 0.0 },
  worldTree:     { label: "世界树",       idleRotateY: 0.05 },
  orbitalChart:  { label: "浑天仪",       idleRotateY: 0.0 },
  pavilion:      { label: "楼阁",         idleRotateY: 0.0 },
  greatWall:     { label: "万里长城",     idleRotateY: 0.03 },
};

/* ---------- helpers ---------- */

function allocate(count: number): { positions: Float32Array; colors: Float32Array; rings: Float32Array } {
  return {
    positions: new Float32Array(count * 3),
    colors: new Float32Array(count * 3),
    rings: new Float32Array(count),
  };
}

function setPoint(
  p: Float32Array,
  c: Float32Array,
  i: number,
  x: number, y: number, z: number,
  r: number, g: number, b: number,
) {
  const pi = i * 3;
  p[pi] = x; p[pi + 1] = y; p[pi + 2] = z;
  c[pi] = r; c[pi + 1] = g; c[pi + 2] = b;
}

function hexToRgb(hex: string): [number, number, number] {
  const n = parseInt(hex.replace("#", ""), 16);
  return [(n >> 16) / 255, ((n >> 8) & 0xff) / 255, (n & 0xff) / 255];
}

/* ---------- 太极（核心造型）----------
 * 金色罗盘式太极：参考传统风水罗盘视觉
 * 由外向内：外符文环带 → 八卦符号环 → 中/内符文环带 → 中心阴阳鱼
 * 整体金色调，明暗分层营造"发光刻纹"质感
 */

// 三爻卦象（先天八卦序）：1=阳爻(连) 0=阴爻(断)，自下而上
const TRIGRAMS: ReadonlyArray<readonly [number, number, number]> = [
  [1, 1, 1], // 乾
  [0, 1, 1], // 巽
  [0, 1, 0], // 坎
  [0, 0, 1], // 艮
  [0, 0, 0], // 坤
  [1, 0, 0], // 震
  [1, 0, 1], // 离
  [1, 1, 0], // 兑
];

export function buildTaiji(count: number, seed = 42): FormationResult {
  const rand = mulberry32(seed);
  const { positions, colors, rings } = allocate(count);

  // ring 分组（罗盘由内→外 0..7）：供 ring-staggered morph 与旋转差速使用
  let cursor = 0;
  const put = (ring: number, x: number, y: number, z: number, col: [number, number, number]) => {
    setPoint(positions, colors, cursor, x, y, z, ...col);
    rings[cursor] = ring;
    cursor++;
  };

  const R = 6.0;
  // 金色系调色板（分量 ≤0.85 防 Bloom 过曝；additive 叠加自然提亮）
  const GOLD_BRIGHT = hexToRgb("#ffd75e"); // 亮金：主环带/阳鱼
  const GOLD_MID    = hexToRgb("#d4a017"); // 中金：卦象/次环带
  const GOLD_DIM    = hexToRgb("#8a6a1f"); // 暗金：阴鱼体/底纹
  const GOLD_WHITE  = hexToRgb("#fff3c4"); // 金白：高光环线/眼
  const FISH_YANG   = hexToRgb("#fffbe6"); // 阳鱼近白金，突出中心

  // 预算分配：环带密 + 中心鱼身高亮突出
  const outerRing   = Math.floor(count * 0.22); // 外符文环带（三道亮环）
  const bagua       = Math.floor(count * 0.15); // 八卦符号（加粗）
  const midRing     = Math.floor(count * 0.17); // 中环带
  const innerRing   = Math.floor(count * 0.13); // 内环带
  const sCurve      = Math.floor(count * 0.08); // 阴阳鱼 S 分界（加粗）
  const eye         = Math.floor(count * 0.04); // 每只眼（放大）
  const fishFill    = count - outerRing - bagua - midRing - innerRing - sCurve - eye * 2;

  const zJitter = (amp: number) => (rand() - 0.5) * amp;

  /* ---- 1) 外符文环带：三道亮环 + 环间密刻纹（实心光带感） ring 7 ---- */
  for (let i = 0; i < outerRing; i++) {
    const theta = rand() * Math.PI * 2;
    const band = rand();
    let r: number;
    let col: [number, number, number];
    if (band < 0.22) { r = R; col = GOLD_WHITE; }               // 最外亮环线
    else if (band < 0.42) { r = R - 0.3; col = GOLD_BRIGHT; }   // 中亮环线
    else if (band < 0.6) { r = R - 0.58; col = GOLD_BRIGHT; }   // 内亮环线
    else { r = R - 0.06 - rand() * 0.5; col = GOLD_MID; }       // 环间符文散点
    put(7, Math.cos(theta) * r, Math.sin(theta) * r, zJitter(0.18), col);
  }

  /* ---- 2) 八卦符号环：8 方位 × 三爻，爻线沿切向（加粗+提亮） ---- */
  const perTrigram = Math.floor(bagua / 8);
  for (let g = 0; g < 8; g++) {
    const az = (g / 8) * Math.PI * 2 + Math.PI / 8;
    const tri = TRIGRAMS[g];
    for (let i = 0; i < perTrigram; i++) {
      const line = Math.floor(rand() * 3);
      const yang = tri[line] === 1;
      const t = rand();
      // 阴爻中段 gap 收窄，使断线仍显形
      if (!yang && Math.abs(t) < 0.10) continue;
      const radial = 4.35 + line * 0.34;
      const tangential = (t - 0.5) * 1.0; // 爻线加长
      // 加宽爻线厚度（径向抖动 ±0.06）
      const radialThick = (rand() - 0.5) * 0.12;
      const x = Math.cos(az) * (radial + radialThick) - Math.sin(az) * tangential;
      const y = Math.sin(az) * (radial + radialThick) + Math.cos(az) * tangential;
      // 爻线用亮金，比环带散点更醒目 ring 6
      put(6, x, y, zJitter(0.12), GOLD_BRIGHT);
    }
  }

  /* ---- 3) 中环带：双亮环 + 密刻纹 ring 5 ---- */
  for (let i = 0; i < midRing; i++) {
    const theta = rand() * Math.PI * 2;
    const band = rand();
    let r: number;
    let col: [number, number, number];
    if (band < 0.3) { r = 3.6; col = GOLD_BRIGHT; }
    else if (band < 0.55) { r = 3.15; col = GOLD_BRIGHT; }
    else { r = 3.2 + rand() * 0.35; col = GOLD_MID; }
    put(5, Math.cos(theta) * r, Math.sin(theta) * r, zJitter(0.18), col);
  }

  /* ---- 4) 内环带：亮环 + 密刻纹 ring 4 ---- */
  for (let i = 0; i < innerRing; i++) {
    const theta = rand() * Math.PI * 2;
    const band = rand();
    const r = band < 0.45 ? 2.6 : 2.25 + rand() * 0.3;
    const col = band < 0.45 ? GOLD_WHITE : GOLD_MID;
    put(4, Math.cos(theta) * r, Math.sin(theta) * r, zJitter(0.15), col);
  }

  /* ---- 5) 中心阴阳鱼：S 分界亮线（加粗） ---- */
  const FISH_R = 2.1; // 放大中心鱼，增强视觉焦点
  for (let i = 0; i < sCurve; i++) {
    const half = i < sCurve / 2 ? 1 : -1;
    const theta = rand() * Math.PI;
    const cy = half * (FISH_R / 2);
    const angle = half === 1 ? theta : -theta;
    // 加宽 S 曲线厚度（±0.14），使分界线更醒目 ring 1
    const thick = (rand() - 0.5) * 0.14;
    const x = Math.cos(angle) * (FISH_R / 2 + thick);
    const y = cy + Math.sin(angle) * (FISH_R / 2 + thick);
    put(1, x, y, zJitter(0.12), GOLD_WHITE);
  }

  /* ---- 6) 阴阳眼（放大） ring 0/1 ---- */
  const eyeR = FISH_R / 4.2;
  for (let k = 0; k < 2; k++) {
    const isYangEye = k === 1;
    const ey = isYangEye ? FISH_R / 2 : -FISH_R / 2;
    const eyeCol = isYangEye ? GOLD_WHITE : GOLD_DIM;
    for (let i = 0; i < eye; i++) {
      const theta = rand() * Math.PI * 2;
      const r = Math.sqrt(rand()) * eyeR;
      put(isYangEye ? 1 : 0,
        Math.cos(theta) * r, ey + Math.sin(theta) * r, zJitter(0.1), eyeCol);
    }
  }

  /* ---- 7) 鱼身填充：阳鱼分配更多点数 + 近白金；阴鱼暗金描边 ring 0/1 ---- */
  const yangFish = Math.floor(fishFill * 0.58); // 阳鱼占比更高，突出中心亮点
  const yinFish  = fishFill - yangFish;
  // 阳鱼（y>0，扣上小圆）ring 0
  let placed = 0;
  while (placed < yangFish && cursor < count) {
    const theta = rand() * Math.PI * 2;
    const r = Math.sqrt(rand()) * (FISH_R - 0.06);
    const x = Math.cos(theta) * r;
    const y = Math.sin(theta) * r;
    if (y <= 0) continue;
    const dx = x, dy = y - FISH_R / 2;
    if (dx * dx + dy * dy < (FISH_R / 2) * (FISH_R / 2)) continue;
    put(0, x, y, zJitter(0.18), FISH_YANG);
    placed++;
  }
  // 阴鱼（y≤0，扣下小圆）——暗金底 + 外缘亮金描边 ring 1
  placed = 0;
  while (placed < yinFish && cursor < count) {
    const theta = rand() * Math.PI * 2;
    const r = Math.sqrt(rand()) * (FISH_R - 0.06);
    const x = Math.cos(theta) * r;
    const y = Math.sin(theta) * r;
    if (y > 0) continue;
    const dx = x, dy = y + FISH_R / 2;
    if (dx * dx + dy * dy < (FISH_R / 2) * (FISH_R / 2)) continue;
    const dist = Math.sqrt(x * x + y * y);
    const rimT = Math.max(0, (dist - (FISH_R - 0.5)) / 0.5);
    put(1, x, y, zJitter(0.18), [
      GOLD_DIM[0] + (GOLD_BRIGHT[0] - GOLD_DIM[0]) * rimT,
      GOLD_DIM[1] + (GOLD_BRIGHT[1] - GOLD_DIM[1]) * rimT,
      GOLD_DIM[2] + (GOLD_BRIGHT[2] - GOLD_DIM[2]) * rimT,
    ]);
    placed++;
  }

  // 若仍有空位，补入外环带散点（避免尾部黑点） ring 7
  while (cursor < count) {
    const theta = rand() * Math.PI * 2;
    const r = R - rand() * 0.5;
    put(7, Math.cos(theta) * r, Math.sin(theta) * r, zJitter(0.3), GOLD_MID);
  }

  return { positions, colors, rings };
}

/* ---------- 九宫八卦阵（太极的立体展开态）----------
 * 与 buildTaiji 共用 ring 分组，保证两态间 per-ring 无缝 morph：
 *   ring 0 中军太极台（立起的双色阴阳盘）
 *   ring 1 八门光环（休生伤杜景死惊开，绕 Y 轴的光环）
 *   ring 2 四正阵（天覆/地载/风扬/云垂，倾斜光盾）
 *   ring 3 四奇阵（龙飞/虎翼/鸟翔/蛇蟠，反倾光盾）
 *   ring 4 48 子小阵（嵌套在八主阵内的点簇）
 *   ring 5 内围游兵环（机动后备，慢速环带）
 *   ring 6 卦象旗标环（八方位三爻旗，悬浮外圈）
 *   ring 7 外围游兵环（最外机动环带）
 * 整体"内圆外方、大阵包小阵"，层间反向差速旋转由顶点着色器 uSpin 驱动。
 */

export function buildBaguaArray(count: number, seed = 42): FormationResult {
  const rand = mulberry32(seed);
  const { positions, colors, rings } = allocate(count);

  let cursor = 0;
  const put = (ring: number, x: number, y: number, z: number, col: [number, number, number]) => {
    setPoint(positions, colors, cursor, x, y, z, ...col);
    rings[cursor] = ring;
    cursor++;
  };

  // 金色系调色板（与罗盘态同源，morph 期间颜色自然过渡）
  const GOLD_BRIGHT = hexToRgb("#ffd75e");
  const GOLD_MID    = hexToRgb("#d4a017");
  const GOLD_DIM    = hexToRgb("#8a6a1f");
  const GOLD_WHITE  = hexToRgb("#fff3c4");
  const FISH_YANG   = hexToRgb("#fffbe6");
  const JADE        = hexToRgb("#7ef0c8"); // 八门/子阵的青玉色，增强科技层次

  // 预算：与罗盘态各 ring 占比大致对齐，减少 morph 时点数密度突变
  const nCore   = Math.floor(count * 0.10); // ring 0 中军
  const nGates  = Math.floor(count * 0.08); // ring 1 八门
  const nZheng  = Math.floor(count * 0.10); // ring 2 四正
  const nQi     = Math.floor(count * 0.10); // ring 3 四奇
  const nSub    = Math.floor(count * 0.20); // ring 4 子小阵
  const nInner  = Math.floor(count * 0.14); // ring 5 内游兵
  const nFlags  = Math.floor(count * 0.15); // ring 6 卦象旗
  // ring 7 外游兵 = 剩余

  const jit = (amp: number) => (rand() - 0.5) * amp;

  /* ---- ring 0：中军太极台 —— 立起的阴阳盘（绕 X 轴 90°，面向观众） ---- */
  const CORE_R = 1.6;
  const halfCore = Math.floor(nCore * 0.5);
  let placed = 0;
  while (placed < halfCore && cursor < count) { // 阳半（右，近白金）
    const theta = rand() * Math.PI * 2;
    const r = Math.sqrt(rand()) * CORE_R;
    const u = Math.cos(theta) * r;             // 盘内横轴
    const v = Math.sin(theta) * r;             // 盘内纵轴
    if (u <= 0) continue;
    const du = u, dv = v - CORE_R / 2;
    if (du * du + dv * dv < (CORE_R / 2) * (CORE_R / 2)) continue;
    put(0, u, v, jit(0.15), FISH_YANG);
    placed++;
  }
  placed = 0;
  while (placed < nCore - halfCore && cursor < count) { // 阴半（左，暗金描边）
    const theta = rand() * Math.PI * 2;
    const r = Math.sqrt(rand()) * CORE_R;
    const u = Math.cos(theta) * r;
    const v = Math.sin(theta) * r;
    if (u > 0) continue;
    const du = u, dv = v + CORE_R / 2;
    if (du * du + dv * dv < (CORE_R / 2) * (CORE_R / 2)) continue;
    const rimT = Math.max(0, (r - (CORE_R - 0.4)) / 0.4);
    put(0, u, v, jit(0.15), [
      GOLD_DIM[0] + (GOLD_BRIGHT[0] - GOLD_DIM[0]) * rimT,
      GOLD_DIM[1] + (GOLD_BRIGHT[1] - GOLD_DIM[1]) * rimT,
      GOLD_DIM[2] + (GOLD_BRIGHT[2] - GOLD_DIM[2]) * rimT,
    ]);
    placed++;
  }
  // 双眼
  for (let k = 0; k < 2; k++) {
    const eu = k === 0 ? CORE_R / 2 : -CORE_R / 2;
    const eyeCol = k === 0 ? GOLD_WHITE : GOLD_DIM;
    for (let i = 0; i < Math.floor(nCore * 0.06); i++) {
      const theta = rand() * Math.PI * 2;
      const r = Math.sqrt(rand()) * (CORE_R / 4.2);
      put(0, eu + Math.cos(theta) * r, Math.sin(theta) * r, jit(0.1), eyeCol);
    }
  }
  // S 分界亮线
  for (let i = 0; i < Math.floor(nCore * 0.12); i++) {
    const half = i % 2 === 0 ? 1 : -1;
    const theta = rand() * Math.PI;
    const cv = half * (CORE_R / 2);
    const angle = half === 1 ? theta : -theta;
    const thick = (rand() - 0.5) * 0.12;
    put(0, Math.cos(angle) * (CORE_R / 2 + thick), cv + Math.sin(angle) * (CORE_R / 2 + thick), jit(0.1), GOLD_WHITE);
  }

  /* ---- ring 1：八门光环 —— y≈0.6 的水平光环，八段明暗对应八门 ---- */
  const GATE_R = 2.6;
  for (let i = 0; i < nGates; i++) {
    const seg = Math.floor(rand() * 8);
    const theta = (seg / 8) * Math.PI * 2 + rand() * (Math.PI / 4);
    const open = seg % 2 === 0; // 开门段更亮
    const r = GATE_R + jit(0.12);
    put(1, Math.cos(theta) * r, 0.6 + jit(0.1), Math.sin(theta) * r,
      open ? GOLD_WHITE : GOLD_MID);
  }

  /* ---- ring 2/3：四正 + 四奇 —— 8 面倾斜光盾，正反交替倾角 ---- */
  const SHIELD_R = 4.2;
  const perShield = Math.floor(nZheng / 4);
  for (let s = 0; s < 4; s++) {
    const az = (s / 4) * Math.PI * 2 + Math.PI / 4; // 四隅方位
    const tilt = 0.5;                                // 向外倾斜
    for (let i = 0; i < perShield; i++) {
      const h = rand() * 2.2 - 0.4;                  // 盾高
      const w = (rand() - 0.5) * 1.6;                // 盾宽（切向）
      const rr = SHIELD_R - h * Math.sin(tilt) * 0.4;
      const x = Math.cos(az) * rr - Math.sin(az) * w;
      const z = Math.sin(az) * rr + Math.cos(az) * w;
      put(2, x, h, z, h > 1.4 ? GOLD_WHITE : GOLD_BRIGHT);
    }
  }
  const perQi = Math.floor(nQi / 4);
  for (let s = 0; s < 4; s++) {
    const az = (s / 4) * Math.PI * 2;                // 四正方位
    const tilt = -0.4;                               // 反倾，与四正交错
    for (let i = 0; i < perQi; i++) {
      const h = rand() * 2.0 - 0.3;
      const w = (rand() - 0.5) * 1.4;
      const rr = SHIELD_R + 0.7 - h * Math.sin(tilt) * 0.4;
      const x = Math.cos(az) * rr - Math.sin(az) * w;
      const z = Math.sin(az) * rr + Math.cos(az) * w;
      put(3, x, h, z, h > 1.3 ? JADE : GOLD_MID);
    }
  }

  /* ---- ring 4：48 子小阵 —— 8 主阵 × 6 簇点团 ---- */
  const perCluster = Math.floor(nSub / 48);
  for (let g = 0; g < 8; g++) {
    const az = (g / 8) * Math.PI * 2 + Math.PI / 8;
    for (let c = 0; c < 6; c++) {
      const ca = az + ((c % 3) - 1) * 0.16;          // 簇在主阵扇区内错开
      const cr = 3.4 + Math.floor(c / 3) * 0.9;
      const cx = Math.cos(ca) * cr;
      const cz = Math.sin(ca) * cr;
      const cy = 0.5 + (c % 2) * 0.8;
      for (let i = 0; i < perCluster; i++) {
        put(4, cx + jit(0.5), cy + jit(0.5), cz + jit(0.5),
          i % 5 === 0 ? GOLD_WHITE : GOLD_MID);
      }
    }
  }

  /* ---- ring 5：内围游兵环 ---- */
  for (let i = 0; i < nInner; i++) {
    const theta = rand() * Math.PI * 2;
    const r = 5.2 + jit(0.25);
    put(5, Math.cos(theta) * r, 0.2 + jit(0.5), Math.sin(theta) * r, GOLD_MID);
  }

  /* ---- ring 6：卦象旗标环 —— 八方位三爻旗，竖直悬浮 ---- */
  const perFlag = Math.floor(nFlags / 8);
  for (let g = 0; g < 8; g++) {
    const az = (g / 8) * Math.PI * 2 + Math.PI / 8;
    const tri = TRIGRAMS[g];
    for (let i = 0; i < perFlag; i++) {
      const line = Math.floor(rand() * 3);
      const yang = tri[line] === 1;
      const t = rand();
      if (!yang && Math.abs(t) < 0.1) continue;      // 阴爻断口
      const h = 1.2 + line * 0.45;                   // 三爻自下而上
      const w = (t - 0.5) * 1.1;                     // 爻宽（切向）
      const rr = 6.4;
      const x = Math.cos(az) * rr - Math.sin(az) * w;
      const z = Math.sin(az) * rr + Math.cos(az) * w;
      put(6, x, h, z, GOLD_BRIGHT);
    }
  }

  /* ---- ring 7：外围游兵环（剩余全部） ---- */
  while (cursor < count) {
    const theta = rand() * Math.PI * 2;
    const r = 7.4 + jit(0.35);
    put(7, Math.cos(theta) * r, -0.2 + jit(0.6), Math.sin(theta) * r,
      rand() < 0.2 ? GOLD_WHITE : GOLD_DIM);
  }

  return { positions, colors, rings };
}

/* ---------- 朱雀 ---------- */

export function buildPhoenix(count: number, seed = 137): FormationResult {
  const rand = mulberry32(seed);
  const { positions, colors, rings } = allocate(count);

  const GOLD   = hexToRgb("#ffd700");
  const ORANGE = hexToRgb("#ff6b00");
  const RED    = hexToRgb("#ff2d00");
  const AMBER  = hexToRgb("#ff8c00");

  const bodyBudget   = Math.floor(count * 0.15);
  const wingBudget   = Math.floor(count * 0.45);
  const crestBudget  = Math.floor(count * 0.05);
  const tailBudget   = count - bodyBudget - wingBudget - crestBudget;

  // ring 分组（由内→外 0..7）：供跨造型 morph 时旋转差速与涟漪展开
  // 0=冠顶, 1=躯干核心, 2-5=翅膀由内到外, 6-7=尾翎末梢
  let cursor = 0;
  const put = (ring: number, x: number, y: number, z: number, col: [number, number, number]) => {
    setPoint(positions, colors, cursor, x, y, z, ...col);
    rings[cursor] = ring;
    cursor++;
  };

  // Body: 沿贝塞尔脊柱分布 → ring 1（核心）
  for (let i = 0; i < bodyBudget; i++) {
    const t = rand();
    // 脊柱控制点 P0(0,-2,0) P1(0,0,0.6) P2(0,2,0)
    const y = (1 - t) * (1 - t) * (-2) + 2 * (1 - t) * t * 0 + t * t * 2;
    const z = (1 - t) * (1 - t) * 0 + 2 * (1 - t) * t * 0.6 + t * t * 0;
    const spread = 0.25 + 0.15 * Math.sin(t * Math.PI);
    const x = (rand() - 0.5) * spread * 2;
    const colT = t;
    const col = colT < 0.5 ? GOLD : ORANGE;
    put(1, x, y, z + (rand() - 0.5) * 0.2, col);
  }

  // Wings: 左右各 wingBudget/2，12 根羽枝扇形 → 按羽毛索引映射 ring 2..5
  const perWing = Math.floor(wingBudget / 2);
  for (let side = -1; side <= 1; side += 2) {
    for (let i = 0; i < perWing; i++) {
      const featherIdx = Math.floor(rand() * 12);
      const t = rand();
      const baseAngle = (featherIdx / 12) * Math.PI * 0.9 + 0.1;
      const len = 2.5 + featherIdx * 0.18;
      const xBase = side * (0.3 + Math.cos(baseAngle) * len * t);
      const yBase = 0.5 + Math.sin(baseAngle) * len * t * 0.7;
      const gauss = (rand() - 0.5) * 0.08;
      const x = xBase + gauss;
      const y = yBase + gauss;
      const z = (rand() - 0.5) * 0.25 - t * 0.3;
      const col = t < 0.4 ? GOLD : t < 0.75 ? ORANGE : RED;
      // 羽毛 0-2 → ring2, 3-5 → ring3, 6-8 → ring4, 9-11 → ring5
      const ring = 2 + Math.min(3, Math.floor(featherIdx / 3));
      put(ring, x, y, z, col);
    }
  }

  // Crest: 三弧冠 → ring 0（最内/最先 morph）
  for (let i = 0; i < crestBudget; i++) {
    const arc = Math.floor(rand() * 3);
    const t = rand();
    const angle = (arc - 1) * 0.4 + t * 0.6;
    const r = 0.6 + t * 0.5;
    const x = Math.sin(angle) * r * 0.5;
    const y = 2.0 + Math.cos(angle) * r;
    const z = (rand() - 0.5) * 0.15;
    put(0, x, y, z, AMBER);
  }

  // Tail: 三根长翎 → ring 6-7（最外/最后 morph）
  for (let i = 0; i < tailBudget; i++) {
    const plume = Math.floor(rand() * 3);
    const t = rand();
    const len = 3.5 + plume * 0.4;
    const sway = Math.sin(t * Math.PI * 2 + plume) * 0.4;
    const x = (plume - 1) * 0.6 + sway;
    const y = -2.0 - t * len;
    const z = (rand() - 0.5) * 0.2 - t * 0.4;
    const col = t < 0.5 ? RED : ORANGE;
    // 尾翎前半 ring6，后半 ring7
    const ring = t < 0.5 ? 6 : 7;
    put(ring, x, y, z, col);
  }

  return { positions, colors, rings };
}

/* ---------- 世界树 ---------- */

export function buildWorldTree(count: number, seed = 2077): FormationResult {
  const rand = mulberry32(seed);
  const { positions, colors, rings } = allocate(count);

  const TEAL_TRUNK  = hexToRgb("#2dd4bf");
  const CYAN_CANOPY = hexToRgb("#06b6d4");
  const WHITE_TIP   = hexToRgb("#ecfeff");

  const trunkBudget   = Math.floor(count * 0.08);
  const branchBudget  = Math.floor(count * 0.22);
  const canopyBudget  = count - trunkBudget - branchBudget;

  // ring 分组（由内→外 0..7）：
  // 0=树干根基, 1-2=一级枝, 3-4=二级枝, 5=三级末梢, 6-7=树冠外层
  let cursor = 0;
  const put = (ring: number, x: number, y: number, z: number, col: [number, number, number] | readonly [number, number, number]) => {
    setPoint(positions, colors, cursor, x, y, z, col[0], col[1], col[2]);
    rings[cursor] = ring;
    cursor++;
  };

  // Trunk y ∈ [-4, 0], r ≈ 0.4 → ring 0（根基核心）
  for (let i = 0; i < trunkBudget; i++) {
    const y = -4 + rand() * 4;
    const theta = rand() * Math.PI * 2;
    const r = Math.sqrt(rand()) * 0.4;
    const x = Math.cos(theta) * r;
    const z = Math.sin(theta) * r;
    put(0, x, y, z, TEAL_TRUNK);
  }

  // Branches: 三层递归简化 — 主干顶部放射出主枝，再分叉
  const branches: Array<{ ox: number; oy: number; oz: number; dx: number; dy: number; dz: number; len: number; level: number }> = [];
  // Level 1: 5 主枝
  for (let i = 0; i < 5; i++) {
    const a = (i / 5) * Math.PI * 2 + rand() * 0.2;
    branches.push({ ox: 0, oy: 0, oz: 0, dx: Math.cos(a), dy: 0.6 + rand() * 0.2, dz: Math.sin(a), len: 2.2, level: 1 });
  }
  // Level 2: 每主枝 3 分枝
  for (let i = 0; i < 5; i++) {
    const parent = branches[i];
    for (let j = 0; j < 3; j++) {
      const t = 0.5 + j * 0.2;
      const px = parent.ox + parent.dx * parent.len * t;
      const py = parent.oy + parent.dy * parent.len * t;
      const pz = parent.oz + parent.dz * parent.len * t;
      const da = (j / 3) * Math.PI * 2 + rand();
      branches.push({ ox: px, oy: py, oz: pz, dx: Math.cos(da) * 0.6 + parent.dx * 0.4, dy: 0.5 + rand() * 0.3, dz: Math.sin(da) * 0.6 + parent.dz * 0.4, len: 1.4, level: 2 });
    }
  }
  // Level 3: 每二级枝 2 末梢
  const l2Count = branches.length;
  for (let i = 5; i < l2Count; i++) {
    const parent = branches[i];
    for (let j = 0; j < 2; j++) {
      const t = 0.6 + j * 0.3;
      const px = parent.ox + parent.dx * parent.len * t;
      const py = parent.oy + parent.dy * parent.len * t;
      const pz = parent.oz + parent.dz * parent.len * t;
      const da = rand() * Math.PI * 2;
      branches.push({ ox: px, oy: py, oz: pz, dx: Math.cos(da) * 0.4, dy: 0.4, dz: Math.sin(da) * 0.4, len: 0.9, level: 3 });
    }
  }

  for (let i = 0; i < branchBudget; i++) {
    const b = branches[Math.floor(rand() * branches.length)];
    const t = rand();
    const x = b.ox + b.dx * b.len * t + (rand() - 0.5) * 0.08;
    const y = b.oy + b.dy * b.len * t + (rand() - 0.5) * 0.08;
    const z = b.oz + b.dz * b.len * t + (rand() - 0.5) * 0.08;
    // level 1 → ring 2, level 2 → ring 4, level 3 → ring 5
    const ring = b.level === 1 ? 2 : b.level === 2 ? 4 : 5;
    put(ring, x, y, z, TEAL_TRUNK);
  }

  // Canopy: 6 个高斯簇 σ≈0.8，分布在枝顶周围
  const centers = [
    [0, 3.2, 0], [1.6, 2.6, 0.8], [-1.6, 2.6, -0.8],
    [0.8, 2.8, -1.6], [-0.8, 2.8, 1.6], [0, 3.6, 0],
  ];
  for (let i = 0; i < canopyBudget; i++) {
    const c = centers[Math.floor(rand() * centers.length)];
    const sigma = 0.8;
    // Box-Muller
    const u1 = Math.max(1e-6, rand());
    const u2 = rand();
    const r = sigma * Math.sqrt(-2 * Math.log(u1));
    const th = u2 * Math.PI * 2;
    const x = c[0] + Math.cos(th) * r;
    const y = c[1] + (rand() - 0.5) * r * 0.8;
    const z = c[2] + Math.sin(th) * r;
    const tipT = Math.min(1, Math.max(0, (y - 2.5) / 1.5));
    const rC = CYAN_CANOPY[0] * (1 - tipT) + WHITE_TIP[0] * tipT;
    const gC = CYAN_CANOPY[1] * (1 - tipT) + WHITE_TIP[1] * tipT;
    const bC = CYAN_CANOPY[2] * (1 - tipT) + WHITE_TIP[2] * tipT;
    // 树冠：内层 ring 6，外层（tipT 高）ring 7
    const ring = tipT > 0.5 ? 7 : 6;
    put(ring, x, y, z, [rC, gC, bC]);
  }

  return { positions, colors, rings };
}

/* ---------- 浑天仪 / 轨道星图 ---------- */

export function buildOrbitalChart(count: number, seed = 888): FormationResult {
  const rand = mulberry32(seed);
  const { positions, colors, rings } = allocate(count);

  const SPHERE_BLUE = hexToRgb("#3b82f6");
  const RING_WHITE  = hexToRgb("#e2e8f0");
  const BAGUA_GOLD  = hexToRgb("#fbbf24");

  const sphereBudget = Math.floor(count * 0.08);
  const ringBudget   = Math.floor(count * 0.60);
  const baguaBudget  = count - sphereBudget - ringBudget;

  // ring 分组（由内→外 0..7）：
  // 0=核心球体, 1-5=五条轨道环由内到外, 6-7=外层八卦 trigrams
  let cursor = 0;
  const put = (ring: number, x: number, y: number, z: number, col: [number, number, number] | readonly [number, number, number]) => {
    setPoint(positions, colors, cursor, x, y, z, col[0], col[1], col[2]);
    rings[cursor] = ring;
    cursor++;
  };

  // Fibonacci sphere r=1.2 → ring 0（核心）
  const phi = (1 + Math.sqrt(5)) / 2;
  for (let i = 0; i < sphereBudget; i++) {
    const y = 1 - (2 * i) / (sphereBudget - 1 || 1);
    const radiusAtY = Math.sqrt(1 - y * y);
    const theta = 2 * Math.PI * i / phi;
    const r = 1.2;
    const x = Math.cos(theta) * radiusAtY * r;
    const z = Math.sin(theta) * radiusAtY * r;
    put(0, x, y * r, z, SPHERE_BLUE);
  }

  // 5 条倾斜轨道环 → ring 1..5（由内到外）
  const perRing = Math.floor(ringBudget / 5);
  for (let k = 0; k < 5; k++) {
    const ringR = 2 + k * 1.2;
    const tiltX = k * 18 * (Math.PI / 180);
    const tiltZ = k * 12 * (Math.PI / 180);
    const ringGroup = k + 1; // ring 1..5
    for (let i = 0; i < perRing; i++) {
      const a = (i / perRing) * Math.PI * 2;
      // 先在 XY 平面取环上点，再绕 X、Z 旋转
      let x = Math.cos(a) * ringR;
      let y = Math.sin(a) * ringR;
      let z = 0;
      // rotate around X
      const y1 = y * Math.cos(tiltX) - z * Math.sin(tiltX);
      const z1 = y * Math.sin(tiltX) + z * Math.cos(tiltX);
      y = y1; z = z1;
      // rotate around Z
      const x2 = x * Math.cos(tiltZ) - y * Math.sin(tiltZ);
      const y2 = x * Math.sin(tiltZ) + y * Math.cos(tiltZ);
      x = x2; y = y2;
      put(ringGroup, x, y, z, RING_WHITE);
    }
  }

  // 八卦 trigram 簇：8 方位 × 3 短划 → ring 7（最外层）
  const perTrigram = Math.floor(baguaBudget / 8);
  for (let g = 0; g < 8; g++) {
    const az = (g / 8) * Math.PI * 2;
    const dist = 5.5;
    const cx = Math.cos(az) * dist;
    const cz = Math.sin(az) * dist;
    for (let i = 0; i < perTrigram; i++) {
      const line = Math.floor(rand() * 3);
      const broken = (g & (1 << line)) !== 0; // 简单映射：二进制位决定断/连
      const ly = (line - 1) * 0.35;
      const t = rand();
      let lx: number;
      if (broken) {
        lx = (t < 0.45 ? -0.3 + t * 0.6 : t > 0.55 ? 0.3 - (1 - t) * 0.6 : NaN);
        if (Number.isNaN(lx)) { cursor++; continue; } // gap（跳过但仍推进 cursor）
      } else {
        lx = -0.3 + t * 0.6;
      }
      // 让卦象面向圆心：局部 x 沿径向
      const rx = cx + Math.cos(az) * lx;
      const rz = cz + Math.sin(az) * lx;
      put(7, rx, ly, rz, BAGUA_GOLD);
    }
  }

  return { positions, colors, rings };
}

/* ---------- 楼阁 ---------- */

export function buildPavilion(count: number, seed = 314): FormationResult {
  const rand = mulberry32(seed);
  const { positions, colors, rings } = allocate(count);

  const VERMILLION = hexToRgb("#dc2626");
  const GOLD       = hexToRgb("#fbbf24");
  const DARK_RED   = hexToRgb("#991b1b");
  const GREEN      = hexToRgb("#16a34a");

  const platformBudget = Math.floor(count * 0.12);
  const pillarBudget   = Math.floor(count * 0.18);
  const roofBudget     = count - platformBudget - pillarBudget;

  // ring 分组（由内→外 0..7）：
  // 0=基座平台, 1=一层柱, 2=二层柱, 3-5=三层屋顶由下到上, 6-7=顶层屋脊/翘檐
  let cursor = 0;
  const put = (ring: number, x: number, y: number, z: number, col: [number, number, number] | readonly [number, number, number]) => {
    setPoint(positions, colors, cursor, x, y, z, col[0], col[1], col[2]);
    rings[cursor] = ring;
    cursor++;
  };

  // Platform 8×6×0.4 → ring 0（基座核心）
  for (let i = 0; i < platformBudget; i++) {
    const x = (rand() - 0.5) * 8;
    const z = (rand() - 0.5) * 6;
    const y = -3 + rand() * 0.4;
    put(0, x, y, z, DARK_RED);
  }

  // Pillars: 两层各 12 根柱 → tier0=ring1, tier1=ring2
  const pillarsPerTier = 12;
  const perPillar = Math.floor(pillarBudget / (pillarsPerTier * 2));
  for (let tier = 0; tier < 2; tier++) {
    const baseY = tier === 0 ? -2.6 : 0.0;
    const height = tier === 0 ? 2.6 : 2.2;
    const radius = tier === 0 ? 3.2 : 2.4;
    const ringGroup = tier + 1; // ring 1 or 2
    for (let p = 0; p < pillarsPerTier; p++) {
      const a = (p / pillarsPerTier) * Math.PI * 2;
      const px = Math.cos(a) * radius;
      const pz = Math.sin(a) * radius;
      for (let i = 0; i < perPillar; i++) {
        const y = baseY + rand() * height;
        const jitter = (rand() - 0.5) * 0.08;
        put(ringGroup, px + jitter, y, pz + jitter, DARK_RED);
      }
    }
  }

  // Roofs: 三层翘檐 → tier0=ring4, tier1=ring5, tier2=ring6（最顶 ring7 留给翘檐尖端）
  for (let tier = 0; tier < 3; tier++) {
    const baseY = tier === 0 ? 0.0 : tier === 1 ? 2.2 : 4.0;
    const roofR = tier === 0 ? 4.0 : tier === 1 ? 3.2 : 2.2;
    const share = Math.floor(roofBudget / 3);
    for (let i = 0; i < share; i++) {
      const theta = rand() * Math.PI * 2;
      const r = Math.sqrt(rand()) * roofR;
      // 屋顶锥面：高度随 r 减小而升高
      const h = (1 - r / roofR) * 1.2;
      // 翘檐：接近外缘时上翻
      const eaveUpturn = 0.6 * Math.pow(Math.max(0, Math.cos(4 * theta)), 3) * (r / roofR);
      const y = baseY + h + eaveUpturn;
      const x = Math.cos(theta) * r;
      const z = Math.sin(theta) * r;
      // 外缘金色，内里朱红，脊线绿色点缀
      const edgeT = r / roofR;
      const col = edgeT > 0.85 ? GOLD : h > 1.0 ? GREEN : VERMILLION;
      // 底层屋顶 ring4，中层 ring5，顶层 ring6；翘檐尖端（edgeT>0.85 且顶层）ring7
      const ring = tier === 2 && edgeT > 0.85 ? 7 : tier + 4;
      put(ring, x, y, z, col);
    }
  }

  return { positions, colors, rings };
}

/* ---------- 万里长城 ---------- */

/**
 * 山脊 + 城墙 + 敌楼 + 垛口 + 云海五段式造型。
 * ring 分层（由远→近 / 由下→上）：
 *   0 云海 · 1 远山(ridge2) · 2 中山(ridge1) · 3 近山(ridge0)
 *   4 城牆走道 · 5  parapet+垛口 · 6 敌楼主体 · 7 敌楼檐顶
 * 预算比：ridges 25% · wall 30% · towers 15% · merlons 10% · clouds 20%（clouds 吸收余量）
 */
export function buildGreatWall(count: number, seed = 777): FormationResult {
  const rand = mulberry32(seed);
  const { positions, colors, rings } = allocate(count);

  // 调色板（RGB ≤ 0.85 防 Bloom 冲白）
  const RIDGE_DARK  = hexToRgb("#2d5a27");
  const RIDGE_LIGHT = hexToRgb("#4a8c3f");
  const WALL_DARK   = hexToRgb("#7a6e5d");
  const WALL_STONE  = hexToRgb("#9c8b75");
  const WALL_LIGHT  = hexToRgb("#b8a892");
  const TOWER_BODY  = hexToRgb("#a08060");
  const TOWER_RIM   = hexToRgb("#c4a060");
  const TOWER_WINDOW = hexToRgb("#d4a840");
  const MERLON_COL  = hexToRgb("#8a7a65");
  // 云海硬限幅 ≤ 0.85
  const CLOUD_WHITE: [number, number, number] = [0.847, 0.85, 0.85];
  const CLOUD_CYAN:  [number, number, number] = [0.659, 0.847, 0.85];

  let cursor = 0;
  const put = (ring: number, x: number, y: number, z: number, col: [number, number, number] | readonly [number, number, number]) => {
    if (cursor >= count) return;
    setPoint(positions, colors, cursor, x, y, z, col[0], col[1], col[2]);
    rings[cursor] = ring;
    cursor++;
  };

  // === 山脊高度函數（確定性，無 rand；三條山脊各自相位偏移）===
  const ridgeBaseY = [-0.5, 0.8, 2.0] as const;
  const ridgeZ     = [-1.5, 0.5, 3.0] as const;
  const ridgePhases = [
    [0.0, 1.2, 2.8],
    [0.7, 2.1, 0.3],
    [2.1, 0.5, 1.8],
  ] as const;
  const ridgeHeight = (x: number, idx: number): number => {
    const p = ridgePhases[idx];
    return (
      ridgeBaseY[idx] +
      1.4 * Math.sin(0.55 * x + p[0]) +
      0.6 * Math.sin(1.3 * x + p[1]) +
      0.3 * Math.sin(2.7 * x + p[2])
    );
  };

  // === 預算分配 ===
  const nRidges  = Math.floor(count * 0.25);
  const nWall    = Math.floor(count * 0.30);
  const nTowers  = Math.floor(count * 0.15);
  const nMerlons = Math.floor(count * 0.10);
  // 餘量全部給雲海，保證總數恆等於 count
  const nClouds  = count - nRidges - nWall - nTowers - nMerlons;

  // --- 1. 山脊（三條，權重 0.40 / 0.35 / 0.25）---
  const ridgeWeights = [0.40, 0.35, 0.25];
  for (let rIdx = 0; rIdx < 3; rIdx++) {
    const n = Math.floor(nRidges * ridgeWeights[rIdx]);
    const ring = rIdx === 0 ? 3 : rIdx === 1 ? 2 : 1; // 近→遠 3/2/1
    for (let i = 0; i < n; i++) {
      const x = -6 + rand() * 12;
      const h = ridgeHeight(x, rIdx);
      // 僅在採樣位置加微抖（不改高度函數本身），讓山體有厚度
      const yJ = (rand() - 0.5) * 0.6;
      const zJ = (rand() - 0.5) * 0.8;
      const y = h + yJ;
      const z = ridgeZ[rIdx] + zJ;
      // 顏色隨高度與隨機混合
      const mix = 0.5 + 0.5 * Math.sin(x * 0.7 + rIdx);
      const base = mix > 0.5 ? RIDGE_LIGHT : RIDGE_DARK;
      const shade = 0.85 + rand() * 0.15;
      put(ring, x, y, z, [base[0] * shade, base[1] * shade, base[2] * shade]);
    }
  }

  // --- 2. 城牆（跟隨中央山脊 ridge1 的脊線 +0.6 偏移）---
  const wallPath = (t: number): [number, number, number] => {
    const x = -5.5 + t * 11;
    const h = ridgeHeight(x, 1) + 0.6;
    const z = ridgeZ[1] + 1.2 * Math.sin(2.5 * t * Math.PI);
    return [x, h, z];
  };
  const EPS = 0.001;
  const normalize3 = (v: [number, number, number]): [number, number, number] => {
    const len = Math.sqrt(v[0] * v[0] + v[1] * v[1] + v[2] * v[2]) || 1;
    return [v[0] / len, v[1] / len, v[2] / len];
  };
  // right = normalize(cross(tangent, (0,1,0))) = normalize((-tz, 0, tx))
  const rightFromTan = (tx: number, tz: number): [number, number, number] => {
    const len = Math.sqrt(tx * tx + tz * tz) || 1;
    return [-tz / len, 0, tx / len];
  };

  const HALF_W = 0.35;
  const PARAPET_H = 0.25;
  for (let i = 0; i < nWall; i++) {
    const t = rand();
    const [cx, cy, cz] = wallPath(t);
    // 切線（中心差分）
    const [xa, ya, za] = wallPath(Math.max(0, t - EPS));
    const [xb, yb, zb] = wallPath(Math.min(1, t + EPS));
    const tan = normalize3([xb - xa, yb - ya, zb - za]);
    const right = rightFromTan(tan[0], tan[2]);

    // 截面 u ∈ [-1,1]；parapet 在 |u|>0.7 處抬高
    const u = (rand() * 2 - 1);
    const edgeFactor = Math.abs(u);
    const yOff = edgeFactor > 0.7 ? PARAPET_H * ((edgeFactor - 0.7) / 0.3) : 0;
    const lateral = u * HALF_W;
    const px = cx + right[0] * lateral;
    const pz = cz + right[2] * lateral;
    const py = cy + yOff + (rand() - 0.5) * 0.08;

    // 顏色：走道偏淺、parapet 偏深
    const base = yOff > 0.05 ? WALL_DARK : edgeFactor < 0.3 ? WALL_LIGHT : WALL_STONE;
    const shade = 0.9 + rand() * 0.1;
    put(4 + (yOff > 0.05 ? 1 : 0), px, py, pz, [base[0] * shade, base[1] * shade, base[2] * shade]);
  }

  // --- 3. 敵樓（4 座，固定 t 位置）---
  const towerTs = [0.15, 0.38, 0.62, 0.85] as const;
  const TOWER_HALF_W = 0.7;
  const TOWER_H = 1.8;
  const RIM_EXTRA = 0.15;
  const RIM_H = 0.3;
  const perTower = Math.floor(nTowers / towerTs.length);
  for (let ti = 0; ti < towerTs.length; ti++) {
    const t = towerTs[ti];
    const [cx, cy, cz] = wallPath(t);
    const pa = wallPath(Math.max(0, t - EPS));
    const pb = wallPath(Math.min(1, t + EPS));
    const tan = normalize3([pb[0] - pa[0], 0, pb[2] - pa[2]]);
    const right = rightFromTan(tan[0], tan[2]);
    // forward = tangent projected on XZ
    const fwd = normalize3([tan[0], 0, tan[2]]);

    for (let i = 0; i < perTower; i++) {
      // 80% 主體 / 20% 檐頂
      const isRim = rand() > 0.8;
      const u = (rand() * 2 - 1);
      const v = (rand() * 2 - 1);
      const lat = u * TOWER_HALF_W;
      const lon = v * TOWER_HALF_W;
      const hFrac = rand();
      const hMax = isRim ? TOWER_H + RIM_H : TOWER_H;
      const wHalf = isRim ? TOWER_HALF_W + RIM_EXTRA : TOWER_HALF_W;
      const latClamped = Math.sign(lat) * Math.min(Math.abs(lat), wHalf);
      const lonClamped = Math.sign(lon) * Math.min(Math.abs(lon), wHalf);

      const px = cx + right[0] * latClamped + fwd[0] * lonClamped;
      const pz = cz + right[2] * latClamped + fwd[2] * lonClamped;
      const py = cy + hFrac * hMax;

      let col: [number, number, number] | readonly [number, number, number] = isRim ? TOWER_RIM : TOWER_BODY;
      // 極少數窗孔點綴
      if (!isRim && rand() > 0.97 && hFrac > 0.4 && hFrac < 0.7 && Math.abs(lat) > 0.4) {
        col = TOWER_WINDOW;
      }
      put(isRim ? 7 : 6, px, py, pz, col);
    }
  }

  // --- 4. 垛口（沿牆兩側，phase-based 方波）---
  for (let i = 0; i < nMerlons; i++) {
    const t = rand();
    // fract(t*28) < 0.5 → 垛口；否則跳過（用餘量填補）
    if ((t * 28) % 1 >= 0.5) {
      // 仍消耗預算但放到牆體同位以避免空洞感
      const [cx, cy, cz] = wallPath(t);
      put(5, cx, cy + 0.05, cz, WALL_STONE);
      continue;
    }
    const [cx, cy, cz] = wallPath(t);
    const pa = wallPath(Math.max(0, t - EPS));
    const pb = wallPath(Math.min(1, t + EPS));
    const tan = normalize3([pb[0] - pa[0], 0, pb[2] - pa[2]]);
    const right = rightFromTan(tan[0], tan[2]);
    const side = rand() > 0.5 ? 1 : -1;
    const u = side * 0.85;
    const px = cx + right[0] * u * HALF_W + (rand() - 0.5) * 0.06;
    const pz = cz + right[2] * u * HALF_W + (rand() - 0.5) * 0.06;
    const py = cy + PARAPET_H + 0.05 + rand() * 0.12;
    put(5, px, py, pz, MERLON_COL);
  }

  // --- 5. 雲海（餘量全入，y 偏低、色溫冷白）---
  for (let i = 0; i < nClouds; i++) {
    const x = (rand() - 0.5) * 13;
    const z = -3 + rand() * 7;
    // pow(rand,0.6) 讓雲層更貼近底部、頂部稀疏
    const y = -3.0 + Math.pow(rand(), 0.6) * 2.2;
    const mix = rand();
    const base = mix > 0.6 ? CLOUD_WHITE : CLOUD_CYAN;
    const alpha = 0.7 + rand() * 0.3;
    put(0, x, y, z, [base[0] * alpha, base[1] * alpha, base[2] * alpha]);
  }

  return { positions, colors, rings };
}

/* ---------- dispatcher ---------- */

export const BUILDERS: Record<FormationKey, (count: number, seed?: number) => FormationResult> = {
  taiji: buildTaiji,
  baguaArray: buildBaguaArray,
  phoenix: buildPhoenix,
  worldTree: buildWorldTree,
  orbitalChart: buildOrbitalChart,
  pavilion: buildPavilion,
  greatWall: buildGreatWall,
};

export function buildFormation(key: FormationKey, count: number, seed?: number): FormationResult {
  return BUILDERS[key](count, seed);
}
