/**
 * 无人机群 GPU morph 着色器
 *
 * 顶点：staggered smoothstep morph + curl swirl during transit + idle breathing + fog
 * 片元：衍射星芒点精灵 + 热核提亮 + per-particle twinkle，配合 AdditiveBlending 形成发光点阵
 */

export const droneVertexShader = /* glsl */ `
uniform float uMorph;   // 0..1 全局 morph 进度
uniform float uTime;    // 累计时间（秒）
uniform float uSize;    // 基础点尺寸
uniform float uPixelRatio;
uniform float uSpin;    // 全局旋转差速强度（仅 taiji/baguaArray 切换时非零）

attribute vec3 aTarget;       // 目标位置
attribute vec3 aColor;        // 当前颜色
attribute vec3 aTargetColor;  // 目标颜色
attribute float aSeed;        // 每粒子 [0,1] 随机种子
attribute float aRing;        // 每粒子 ring group 0..7（用于 per-ring stagger + 旋转差速）
attribute float aTargetRing;  // 目标造型的 ring group（morph 期间插值用）

varying vec3 vColor;
varying float vSeed;
varying float vPointSize;

#include <fog_pars_vertex>

// per-ring stagger：内环先动、外环后动，形成由内向外的涟漪展开/收拢
// ring 0..7 → delay 0..0.56；同环内仍叠加 aSeed 微抖动避免整环齐步走
float ringStaggeredMorph(float m, float ring, float seed) {
  float ringDelay = ring * 0.08;            // 环间延迟 0.08
  float jitter    = seed * 0.12;            // 环内抖动
  float delay     = clamp(ringDelay + jitter, 0.0, 0.75);
  float span      = 1.0 - delay;
  float local     = clamp((m - delay) / max(span, 0.001), 0.0, 1.0);
  return local * local * (3.0 - 2.0 * local); // smoothstep
}

// Y 轴旋转矩阵
mat2 rotY(float a) {
  float c = cos(a); float s = sin(a);
  return mat2(c, -s, s, c);
}

// 旋涡位移：用全局 uMorph 驱动包络，保证所有环同步进入/退出 swirl，
// 避免内环先卷外环静止造成的非对称闪烁
vec3 curlDisplacement(vec3 from, vec3 to, float globalMorph, float seed) {
  vec3 dir = to - from;
  float len = length(dir);
  if (len < 0.001) return vec3(0.0);
  vec3 n = normalize(dir);
  // 构造正交基
  vec3 up = abs(n.y) < 0.9 ? vec3(0.0, 1.0, 0.0) : vec3(1.0, 0.0, 0.0);
  vec3 b1 = normalize(cross(n, up));
  vec3 b2 = cross(n, b1);
  float angle = (seed * 6.2831853 + uTime * 1.5) + globalMorph * 6.2831853;
  // 包络用全局 morph：sin(π·uMorph) 在 0/1 处为 0、0.5 处峰值
  // 起始偏移 0.08 使 swirl 不与 breathing 抑制窗口完全重叠
  float envelope = sin(clamp(globalMorph - 0.08, 0.0, 1.0) * 3.14159265);
  float radius = len * 0.15 * envelope;
  return (b1 * cos(angle) + b2 * sin(angle)) * radius;
}

void main() {
  // ring 在 morph 期间线性插值，用于差速旋转的瞬时权重
  float ringNow = mix(aRing, aTargetRing, uMorph);

  // per-ring staggered morph：内环先动外环后动（仅影响位置插值进度）
  float m = ringStaggeredMorph(uMorph, ringNow, aSeed);

  // 旋转差速：每环独立绕 Y 轴旋转，奇偶环反向，内快外慢
  // 仅在 uSpin != 0 时激活（taiji↔baguaArray 切换态或 hold 态的科技感动效）
  float dir = mod(ringNow, 2.0) < 1.0 ? 1.0 : -1.0;
  float speed = (8.0 - ringNow) * 0.07 * dir;        // ring0 最快 ~0.56, ring7 最慢 ~0.07
  float angle = uTime * speed * uSpin;
  mat2 ry = rotY(angle);

  // 对当前/目标位置分别施加各自 ring 的旋转，再 mix → 避免旋转与 morph 错位
  vec3 pFrom = position;  pFrom.xz = ry * pFrom.xz;
  vec3 pTo   = aTarget;   pTo.xz   = ry * pTo.xz;

  vec3 pos = mix(pFrom, pTo, m);
  // curl 用全局 uMorph 而非局部 m → 所有环同步 swirl，消除非对称闪烁
  pos += curlDisplacement(pFrom, pTo, uMorph, aSeed);

  // Idle breathing：morph 期间平滑抑制，窗口放宽至 0.35 避免与 curl  onset 叠加
  float breathe = sin(uTime * 1.2 + aSeed * 6.2831853) * 0.04;
  float breatheMask = 1.0 - smoothstep(0.0, 0.35, uMorph) * (1.0 - smoothstep(0.75, 1.0, uMorph));
  pos += normalize(pos + vec3(0.0001)) * breathe * breatheMask;

  vec4 mvPosition = modelViewMatrix * vec4(pos, 1.0);
  gl_Position = projectionMatrix * mvPosition;

  // 透视衰减点大小：uSize=1.2、距离 ~24 时约 7px；clamp 上限收紧防近距糊屏
  float size = uSize * uPixelRatio * (140.0 / max(-mvPosition.z, 0.001));
  gl_PointSize = clamp(size, 1.0, 18.0);

  vColor = mix(aColor, aTargetColor, m);
  vSeed = aSeed;
  vPointSize = gl_PointSize;

  #include <fog_vertex>
}
`;

export const droneFragmentShader = /* glsl */ `
uniform float uTime;
uniform float uTwinkleAmp;    // tier 门控：high 0.45 / medium 0.25 / low 0
uniform float uSpikeStrength; // tier 门控：high 0.7 / medium 0.4 / low 0

varying vec3 vColor;
varying float vSeed;
varying float vPointSize;

#include <fog_pars_fragment>

void main() {
  vec2 uv = gl_PointCoord - vec2(0.5);
  float dist = length(uv);

  // 软边圆点基底
  float baseAlpha = 1.0 - smoothstep(0.15, 0.5, dist);

  // 衍射星芒：四向十字高光，模拟镜头衍射；小点（<3px）自动退化为纯圆点防摩尔纹
  float spike = pow(abs(uv.x * uv.y), 0.15);
  float spikeGlow = exp(-dist * dist * 12.0) + spike * exp(-dist * 6.0) * 0.6;
  float spikeMix = uSpikeStrength * smoothstep(2.0, 4.0, vPointSize);
  float alpha = baseAlpha * mix(1.0, spikeGlow, spikeMix);
  if (alpha < 0.01) discard;

  // 二次衰减压低单点亮度：additive blending 下万点叠加才不会冲白
  alpha *= alpha;

  // 中心热核提亮（保留灯珠感但收敛增益）
  float core = exp(-dist * dist * 18.0);
  vec3 color = vColor * (0.85 + core * 0.5);

  // Per-particle twinkle：错频闪烁，静态 hold 阶段也有生命感
  float tw = sin(uTime * (8.0 + vSeed * 12.0) + vSeed * 62.83);
  tw = smoothstep(0.3, 0.9, tw);
  color *= mix(1.0, mix(0.55, 1.0, tw), uTwinkleAmp);

  gl_FragColor = vec4(color, alpha);

  #include <fog_fragment>
}
`;
