import { useEffect, useRef } from "react";
import { useFrame } from "@react-three/fiber";
import * as THREE from "three";
import { FORMATION_ORDER } from "../formations";
import { droneCountForTier, useDroneShowStore } from "../store";
import {
  applyFormationToTargets,
  commitTargetsToCurrent,
  setMorphUniform,
} from "../scene/swarmOps";

const HOLD_DURATION = 8; // 秒（speed=1 时）
const MORPH_DURATION = 3;

// taiji↔baguaArray 切换专用：延长 morph、hold 期间启用旋转差速增强科技感
const TAIJI_BAGUA_MORPH_DURATION = 4.5;
const SPIN_HOLD_STRENGTH = 0.6;   // hold 态的旋转强度（柔和持续转动）
const SPIN_MORPH_STRENGTH = 1.0;  // morph 态峰值旋转强度

/** easeInOutCubic */
function easeInOutCubic(t: number): number {
  return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
}

/** 判断两个造型索引是否构成 taiji↔baguaArray 配对 */
function isTaijiBaguaPair(a: number, b: number): boolean {
  const pair = [0, 1]; // FORMATION_ORDER[0]=taiji, [1]=baguaArray
  return (a === pair[0] && b === pair[1]) || (a === pair[1] && b === pair[0]);
}

/** 设置 uSpin uniform（缺省安全） */
function setSpinUniform(points: THREE.Points, value: number) {
  const mat = points.material as THREE.ShaderMaterial;
  if (mat?.uniforms?.uSpin) mat.uniforms.uSpin.value = value;
}

/**
 * MorphDriver：驱动 DroneSwarm 的 hold → morph → hold 循环
 *
 * 通过 ref 直接操作 Points，避免每帧 React 状态更新。
 * store.formationIndex 变化时立即切入新目标并启动 morph。
 */
export function MorphDriver({ pointsRef }: { pointsRef: React.RefObject<THREE.Points | null> }) {
  const stateRef = useRef({
    phase: "hold" as "hold" | "morph",
    elapsed: 0,
    lastFormationIndex: 0,
    pendingManual: false,
  });

  // 订阅 store（在 useFrame 外读取以避免每帧 selector 开销）
  const playingRef       = useRef(true);
  const speedRef         = useRef(1);
  const formationIdxRef  = useRef(0);
  const qualityRef       = useRef<"high" | "medium" | "low">("high");

  // 同步 ref（放进 effect：订阅回调只在 store 变更时执行，不在渲染期读 ref）
  useEffect(() => useDroneShowStore.subscribe((s) => {
    playingRef.current      = s.playing;
    speedRef.current        = s.speed;
    formationIdxRef.current = s.formationIndex;
    qualityRef.current      = s.qualityTier;
  }), []);

  const setMorphProgress = useDroneShowStore((s) => s.setMorphProgress);

  // 初始化：确保 target = current（taiji），uMorph=0
  useEffect(() => {
    const pts = pointsRef.current;
    if (!pts) return;
    const count = droneCountForTier(qualityRef.current);
    applyFormationToTargets(pts, "taiji", count, 42);
    commitTargetsToCurrent(pts, count);
    applyFormationToTargets(pts, FORMATION_ORDER[1], count);
    setMorphUniform(pts, 0);
    stateRef.current.lastFormationIndex = 0;
    stateRef.current.phase = "hold";
    stateRef.current.elapsed = 0;
  }, [pointsRef]);

  useFrame((_, delta) => {
    const pts = pointsRef.current;
    if (!pts) return;

    const st = stateRef.current;
    const playing = playingRef.current;
    const speed   = speedRef.current;
    const idx     = formationIdxRef.current;
    const count   = droneCountForTier(qualityRef.current);

    // 检测外部切换（HUD 点击或键盘）：target 从"当前已确认造型"重建，
    // 避免自动轮播 morph 中途手动切换时 from==to 导致画面静止
    if (idx !== st.lastFormationIndex) {
      applyFormationToTargets(pts, FORMATION_ORDER[st.lastFormationIndex], count);
      commitTargetsToCurrent(pts, count);
      applyFormationToTargets(pts, FORMATION_ORDER[idx], count);
      setMorphUniform(pts, 0);
      st.phase = "morph";
      st.elapsed = 0;
      st.lastFormationIndex = idx;
    }

    if (!playing) {
      // 暂停时仅保持当前 uMorph；taiji/baguaArray hold 态仍维持旋转差速以保持科技感
      const curKey = FORMATION_ORDER[idx];
      if (curKey === "taiji" || curKey === "baguaArray") {
        setSpinUniform(pts, SPIN_HOLD_STRENGTH);
      } else {
        setSpinUniform(pts, 0);
      }
      return;
    }

    const dt = delta * speed;
    st.elapsed += dt;

    // 当前/下一造型是否 taiji↔baguaArray 配对 → 决定 morph 时长与 uSpin
    const isPairNow = isTaijiBaguaPair(idx, st.lastFormationIndex);

    if (st.phase === "hold") {
      const holdDur = HOLD_DURATION; // hold 时长不因配对变化
      // hold 期间：若当前是 taiji/baguaArray，启用柔和旋转
      const curKey = FORMATION_ORDER[idx];
      if (curKey === "taiji" || curKey === "baguaArray") {
        setSpinUniform(pts, SPIN_HOLD_STRENGTH);
      } else {
        setSpinUniform(pts, 0);
      }

      if (st.elapsed >= holdDur) {
        // 进入下一造型的 morph
        const nextIdx = (idx + 1) % FORMATION_ORDER.length;
        applyFormationToTargets(pts, FORMATION_ORDER[nextIdx], count);
        setMorphUniform(pts, 0);
        st.phase = "morph";
        st.elapsed = 0;
        // 注意：不在这里改 store.formationIndex，让 on-morph-complete 统一更新
      } else {
        setMorphProgress(0);
      }
    } else {
      // morph：taiji↔baguaArray 配对使用更长时长 + 强旋转
      const nextIdx = (idx + 1) % FORMATION_ORDER.length;
      const isPairMorph = isTaijiBaguaPair(idx, nextIdx) || isPairNow;
      const morphDur = isPairMorph ? TAIJI_BAGUA_MORPH_DURATION : MORPH_DURATION;
      const raw = Math.min(st.elapsed / morphDur, 1);
      const eased = easeInOutCubic(raw);
      setMorphUniform(pts, eased);
      setMorphProgress(raw);

      // morph 期间 uSpin 用 sin 包络：中段最强、两端平滑衔接 hold 态
      if (isPairMorph) {
        const envelope = Math.sin(raw * Math.PI); // 0→1→0
        setSpinUniform(pts, SPIN_HOLD_STRENGTH + (SPIN_MORPH_STRENGTH - SPIN_HOLD_STRENGTH) * envelope);
      } else {
        setSpinUniform(pts, 0);
      }

      if (raw >= 1) {
        // 完成：target → current。下一目标留待 hold 结束 / 手动切换时写入，
        // 避免"预填下下个造型"与 store 异步更新叠加出 from==to 的静止 morph
        commitTargetsToCurrent(pts, count);
        const completedIdx = (idx + 1) % FORMATION_ORDER.length;
        setMorphUniform(pts, 0);
        st.phase = "hold";
        st.elapsed = 0;
        st.lastFormationIndex = completedIdx;
        // 同步 store（触发 HUD 高亮切换）
        useDroneShowStore.getState().setFormation(completedIdx);
        setMorphProgress(0);
      }
    }
  });

  return null;
}
