import * as THREE from "three";
import { buildFormation, type FormationKey } from "../formations";

/**
 * 无人机群 buffer 操作接口（独立模块，供 MorphDriver 驱动 morph 状态机）
 */

/** 把新造型写入 target buffer，触发 morph */
export function applyFormationToTargets(
  points: THREE.Points,
  key: FormationKey,
  count: number,
  seed?: number,
) {
  const geo = points.geometry;
  const aTarget      = geo.attributes.aTarget as THREE.BufferAttribute;
  const aTargetColor = geo.attributes.aTargetColor as THREE.BufferAttribute;
  const aTargetRing  = geo.attributes.aTargetRing as THREE.BufferAttribute | undefined;
  const result = buildFormation(key, count, seed);
  (aTarget.array as Float32Array).set(result.positions.subarray(0, count * 3));
  (aTargetColor.array as Float32Array).set(result.colors.subarray(0, count * 3));
  if (aTargetRing && result.rings) {
    (aTargetRing.array as Float32Array).set(result.rings.subarray(0, count));
    aTargetRing.needsUpdate = true;
  }
  aTarget.needsUpdate = true;
  aTargetColor.needsUpdate = true;
}

/** morph 完成后把 target 拷回 current，准备下一轮 */
export function commitTargetsToCurrent(points: THREE.Points, count: number) {
  const geo = points.geometry;
  const position     = geo.attributes.position as THREE.BufferAttribute;
  const color        = geo.attributes.aColor as THREE.BufferAttribute;
  const aTarget      = geo.attributes.aTarget as THREE.BufferAttribute;
  const aTargetColor = geo.attributes.aTargetColor as THREE.BufferAttribute;
  const aRing        = geo.attributes.aRing as THREE.BufferAttribute | undefined;
  const aTargetRing  = geo.attributes.aTargetRing as THREE.BufferAttribute | undefined;
  (position.array as Float32Array).set((aTarget.array as Float32Array).subarray(0, count * 3));
  (color.array as Float32Array).set((aTargetColor.array as Float32Array).subarray(0, count * 3));
  if (aRing && aTargetRing) {
    (aRing.array as Float32Array).set((aTargetRing.array as Float32Array).subarray(0, count));
    aRing.needsUpdate = true;
  }
  position.needsUpdate = true;
  color.needsUpdate = true;
}

export function setMorphUniform(points: THREE.Points, value: number) {
  const mat = points.material as THREE.ShaderMaterial;
  if (mat?.uniforms?.uMorph) {
    mat.uniforms.uMorph.value = value;
  }
}
