import { useRef } from "react";
import { Stars, OrbitControls, Grid, Sparkles } from "@react-three/drei";
import {
  EffectComposer,
  Bloom,
  Noise,
  Vignette,
  ToneMapping,
  HueSaturation,
  SMAA,
  FXAA,
} from "@react-three/postprocessing";
import { BlendFunction, ToneMappingMode } from "postprocessing";
import * as THREE from "three";
import { DroneSwarm } from "./DroneSwarm";
import { MorphDriver } from "../systems/MorphDriver";
import { useDroneShowStore } from "../store";

/**
 * 光电渲染主场景
 * - 黑色夜空 + FogExp2 深度雾（粒子/星空自然淡出）
 * - drei Grid 地面参考面（替代 canvas 渐变平面，更精致）
 * - drei Sparkles 环境微光（tier 门控）
 * - 后处理链：SMAA/FXAA → ACES ToneMapping → Bloom → 饱和度补偿 → 胶片噪点 → 暗角
 */
export function DroneScene() {
  const pointsRef = useRef<THREE.Points>(null);
  const autoOrbit = useDroneShowStore((s) => s.autoOrbit);
  const qualityTier = useDroneShowStore((s) => s.qualityTier);

  // fog 密度按 tier 调整：high 稀薄保留远景细节，low 浓雾遮丑
  const fogDensity = qualityTier === "high" ? 0.015 : qualityTier === "medium" ? 0.02 : 0.025;
  // Grid fadeDistance 按 tier 收缩
  const gridFade = qualityTier === "high" ? 50 : qualityTier === "medium" ? 40 : 30;

  return (
    <>
      {/* 强制黑色背景 */}
      <color attach="background" args={["#000000"]} />

      {/* 指数雾：与黑色背景同色，远处粒子/星空平滑淡出 */}
      <fogExp2 attach="fog" args={["#000000", fogDensity]} />

      {/* 星空 */}
      <Stars radius={100} depth={50} count={3000} saturation={0} fade speed={0.6} />

      {/* 地面网格：infiniteGrid + DoubleSide 防俯视穿帮；y=-4.85 避免与 y=-5 旧平面 z-fighting */}
      <Grid
        position={[0, -4.85, 0]}
        args={[100, 100]}
        cellSize={2}
        cellThickness={0.5}
        cellColor="#1a3366"
        sectionSize={10}
        sectionThickness={1}
        sectionColor="#334488"
        fadeDistance={gridFade}
        fadeStrength={1}
        infiniteGrid
        side={THREE.DoubleSide}
      />

      {/* 环境微光漂浮（low tier 关闭以省 draw call） */}
      {qualityTier !== "low" && (
        <Sparkles
          count={qualityTier === "high" ? 600 : 250}
          scale={[24, 14, 24]}
          size={2}
          speed={0.25}
          opacity={0.5}
          color="#7fb2ff"
          noise={0.5}
        />
      )}

      {/* 无人机群（ref 由 DroneSwarm 自己持有并回传，供 MorphDriver 驱动） */}
      <DroneSwarm pointsRef={pointsRef} />
      <MorphDriver pointsRef={pointsRef} />

      {/* 相机控制 */}
      <OrbitControls
        enablePan={false}
        enableDamping
        dampingFactor={0.08}
        minDistance={8}
        maxDistance={45}
        maxPolarAngle={Math.PI * 0.85}
        autoRotate={autoOrbit}
        autoRotateSpeed={0.4}
      />

      {/* 后处理链（按 tier 分级）
          Canvas antialias=false，由 SMAA/FXAA 接管 AA，避免双重 AA 开销
          ToneMapping(ACES_FILMIC) 放在 Bloom 之后：Bloom 在 linear 空间累积，
          ACES 压缩高光同时保留灯珠色彩层次；HueSaturation 补偿 ACES 的固有去饱和 */}
      {qualityTier === "high" && (
        <EffectComposer multisampling={0}>
          <SMAA />
          <Bloom
            mipmapBlur
            luminanceThreshold={0.6}
            luminanceSmoothing={0.15}
            intensity={0.7}
            radius={0.8}
          />
          <ToneMapping mode={ToneMappingMode.ACES_FILMIC} />
          <HueSaturation saturation={0.15} />
          <Noise
            blendFunction={BlendFunction.OVERLAY}
            opacity={0.04}
            premultiply
          />
          <Vignette offset={0.3} darkness={0.8} />
        </EffectComposer>
      )}
      {qualityTier === "medium" && (
        <EffectComposer multisampling={0}>
          <FXAA />
          <ToneMapping mode={ToneMappingMode.ACES_FILMIC} />
          <Noise
            blendFunction={BlendFunction.SOFT_LIGHT}
            opacity={0.03}
            premultiply
          />
          <Vignette offset={0.3} darkness={0.7} />
        </EffectComposer>
      )}
      {/* low tier: 无后处理，零额外开销 */}
    </>
  );
}
